  function reset() { const v = visit(); if (v && v.status === 'BROWSING') { v.status = 'ABANDONED'; ev(v, 'abandoned', 'Left at “' + K.step + '”'); FF.save(); } clearInterval(K.timer); stopCam(); while ($('.scrim')) FF.closeOverlay(); K = fresh(); FF.lang = q.get('lang') || 'en'; render(); }

